import kotlin.reflect.*

class Foo<T>
class Outer { class Inner; inner class In2 }
interface Marker
enum class Color { RED }
object Obj
open class Base
fun <T> gen(): Foo<T> = Foo()

inline fun <reified T> show() { println(typeOf<T>()) }
fun <T> nonReified(): KType = typeOf<List<T>>()
inline fun <reified A, reified B> pairType(): KType = typeOf<Pair<A, B?>>()
open class Animal
class Dog : Animal()
interface Walker
class Cat : Animal(), Walker

fun main() {
    println(typeOf<Int>())
    println(typeOf<Int?>())
    println(typeOf<String>())
    println(typeOf<Any>())
    println(typeOf<Any?>())
    println(typeOf<List<Int>>())
    println(typeOf<List<Int?>>())
    println(typeOf<MutableList<String>>())
    println(typeOf<Map<String, List<Int>>>())
    println(typeOf<Map<String, *>>())
    println(typeOf<List<out Number>>())
    println(typeOf<Comparable<in Int>>())
    println(typeOf<Array<String>>())
    println(typeOf<Array<Int>>())
    println(typeOf<IntArray>())
    println(typeOf<Foo<Int>>())
    println(typeOf<Foo<*>>())
    println(typeOf<Outer.Inner>())
    println(typeOf<Marker>())
    println(typeOf<Color>())
    println(typeOf<Obj>())
    println(typeOf<Base?>())
    println(typeOf<Unit>())
    println(typeOf<Pair<Int, String>>())
    println(typeOf<(Int) -> String>())
    println(typeOf<Long>())
    println(typeOf<Double>())
    println(typeOf<Boolean>())
    println(typeOf<Char>())
    println(typeOf<Byte>())
    println(typeOf<Float>())
    println(typeOf<Short>())
    println(typeOf<Set<Char>>())
    println(typeOf<Collection<Int>>())
    println(typeOf<Iterable<Int>>())
    println(typeOf<Map.Entry<String, Int>>())
    println(typeOf<UInt>())
    println(typeOf<Number>())
    println(typeOf<CharSequence>())
    println(typeOf<Throwable>())
    show<Int>()
    show<List<String>?>()
    val t = typeOf<Map<String, List<Int>>>()
    println(t.classifier)
    println(t.classifier == Map::class)
    println(t.arguments)
    println(t.arguments[1].type)
    println(t.arguments[1].variance)
    println(t.isMarkedNullable)
    println(typeOf<Int?>().isMarkedNullable)
    println(typeOf<Int>().classifier == Int::class)
    println(typeOf<Int>() == typeOf<Int>())
    println(typeOf<Int>() == typeOf<Int?>())
    println(typeOf<List<Int>>() == typeOf<List<Int>>())
    println(typeOf<List<Int>>() == typeOf<List<String>>())
    println(typeOf<List<Int>>().hashCode() == typeOf<List<Int>>().hashCode())
    println(typeOf<Map<String, *>>().arguments[1])
    println(typeOf<Map<String, *>>().arguments[1].type)
    println(typeOf<Map<String, *>>().arguments[1].variance)
    println(KTypeProjection.STAR)
    println(KTypeProjection.invariant(typeOf<Int>()))
    println(KTypeProjection.covariant(typeOf<Int>()))
    println(KTypeProjection.contravariant(typeOf<Int>()))
    println(KTypeProjection(KVariance.IN, typeOf<String>()))
    println(KTypeProjection.STAR == KTypeProjection(null, null))
    println(KVariance.values().toList())
    println(KTypeProjection.covariant(typeOf<Int>()).copy(variance = KVariance.IN))
    println(KTypeProjection.invariant(typeOf<Int>()).component1())
    println(KTypeProjection.invariant(typeOf<Int>()).component2())
    println(nonReified<Int>())
    val p = nonReified<Int>().arguments[0].type!!.classifier
    println(p is KTypeParameter)
    println((p as KTypeParameter).name)
    println(p.variance)
    println(p.isReified)
    println(p.upperBounds)
    println(pairType<String, Int>())
    println(pairType<List<Int>, Map<String, Int>>())
    println(typeOf<Foo<Foo<List<Int>>>>().arguments[0].type!!.arguments[0].type!!.arguments)
    println(typeOf<List<(Int) -> String>>())
    println(typeOf<((Int, String) -> Unit)?>())
    println(typeOf<(Int) -> String>().arguments)
    println(typeOf<Int>().classifier)
    println(typeOf<Dog>().classifier == Dog::class)
    println(Animal::class.isInstance(Dog()))
    println(Animal::class.isInstance(Cat()))
    println(Dog::class.isInstance(Cat()))
    println(Walker::class.isInstance(Cat()))
    println(Walker::class.isInstance(Dog()))
    println(Animal::class.isInstance(null))
    println(String::class.isInstance("x"))
    println(Int::class.isInstance(5))
    println(Int::class.isInstance("x"))
    println(Any::class.isInstance(5))
    val a: Animal = Dog()
    println(Dog::class.cast(a) === a)
    println(Dog::class.safeCast(a) === a)
    println(Cat::class.safeCast(a))
    try { Cat::class.cast(a) } catch (e: ClassCastException) { println(e.message) }
    println(String::class.cast("s"))
}
